from pathlib import Path
import json, html, shutil, re
from urllib.parse import quote, urlparse
ROOT=Path(__file__).resolve().parents[1]; DIST=ROOT/'dist'
books=json.loads((ROOT/'data/catalog.json').read_text()); config=json.loads((ROOT/'data/site.json').read_text())
assert config['commerceMode']=='external', 'Vendas próprias exigem backend implementado e homologado.'
DIST.mkdir(exist_ok=True)
def e(s): return html.escape(str(s or ''),quote=True)
def href(s): return quote(s,safe='/.-_')
# Use the larger original artwork, including its red background.
def asset(b): return href(b['cover'])
for b in books:
    for file in {b['cover'],b.get('thumbnail',b['cover'])}:
        dest=DIST/file;dest.parent.mkdir(exist_ok=True,parents=True);shutil.copyfile(ROOT.parent/file,dest)
logo='images/imagem colada 454x98.jpg';shutil.copyfile(ROOT.parent/logo,DIST/logo)
for f in ('style.css','editorial.css','catalog.js'):shutil.copyfile(ROOT/'src'/f,DIST/f)
def page(name,title,body,description='',schema=None):
    current='catalogo.html' if name in [b['legacyPath'] for b in books] else name
    nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if current==url else '')+(' class="catalog-link"' if url=='catalogo.html' else '')+f'>{label}</a>' for url,label in [('index.html','Início'),('catalogo.html','Catálogo'),('sobreaeditora.html','A editora'),('contato.html','Contato')])
    canonical=''
    if config['canonicalOrigin']:canonical=f'<link rel="canonical" href="{e(config["canonicalOrigin"].rstrip("/")+"/"+href(name))}">'
    robots='index,follow' if config['indexable'] else 'noindex,nofollow'
    structured='<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False).replace('<','\\u003c')+'</script>' if schema else ''
    doc=f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | Terceiro Nome</title><meta name="description" content="{e(description or 'Conheça os livros da Editora Terceiro Nome. Consulte o catálogo, descubra autores e encontre sua próxima leitura.')}"><meta name="robots" content="{robots}">{canonical}<meta name="theme-color" content="#f5f3ed"><meta property="og:title" content="{e(title)} | Terceiro Nome"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website"><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="editorial.css">{structured}<script src="catalog.js" defer></script></head><body><a class="skip" href="#conteudo">Pular para o conteúdo</a><div class="topline">Uma casa de livros, muitas formas de ver o Brasil.</div><div class="wrap"><header class="header"><a class="logo" href="index.html" aria-label="Terceiro Nome — início"><img src="{href(logo)}" width="454" height="98" alt="Editora Terceiro Nome"></a><nav class="nav" aria-label="Navegação principal">{nav}</nav></header><main id="conteudo">{body}</main><footer class="footer"><div><strong>Livros para olhar mais longe.</strong><p>Editora Terceiro Nome. O Brasil, suas raízes, suas belezas e seus desafios.</p></div><nav aria-label="Rodapé"><a href="catalogo.html">Catálogo</a><a href="sobreaeditora.html">A editora</a><a href="contato.html">Contato</a><a href="{config['contactInstagram']}" rel="noopener noreferrer" target="_blank">Instagram ↗</a></nav></footer><div class="bottom">Editora Terceiro Nome · Compras realizadas no site da Martins Fontes Paulista.</div></div></body></html>'''
    (DIST/name).write_text(doc)
def card(b):
    collection=b['collection'] or 'Outros títulos'
    return f'''<article class="book" data-title="{e(b['title'])}" data-author="{e(b['author'])}" data-collection="{e(collection)}" data-search="{e(' '.join([b['title'],b['author'],b['isbn'] or '',b['collection']]))}"><a href="{href(b['legacyPath'])}"><div class="cover"><img src="{asset(b)}" alt="Capa de {e(b['title'])}" loading="lazy" width="350" height="450"></div><span class="tag">{e(b['collection'] or 'Terceiro Nome')}</span><h3>{e(b['title'])}</h3><p class="author">{e(b['author'])}</p></a></article>'''
by_id={b['id']:b for b in books}
featured=[by_id[k] for k in ['zoe','a-flecha','nunca-o-nome-do-menino','ocio']]
hero=f'''<section class="hero"><div class="hero-meta"><span>Literatura · Arte · Antropologia</span><span>Uma editora. Muitos olhares.</span></div><div class="hero-layout"><div><h1>Ler o Brasil.<br>Rever o<br><em>mundo.</em></h1><p>Há livros que abrem caminhos. Outros mudam a maneira de olhar. Encontre os seus na Terceiro Nome.</p><a class="button" href="catalogo.html">Explore o catálogo <span aria-hidden="true">↗</span></a></div><figure class="hero-figure"><span class="vertical-note">Um encontro com outras formas de viver</span><a href="zoe.html"><img src="{asset(by_id['zoe'])}" alt="Zoé, de Rogério Assis — conheça o livro" width="700" height="900" fetchpriority="high"></a><figcaption><div><strong>Zoé</strong><br><span>Rogério Assis · Fotografia</span></div><a href="zoe.html" aria-label="Conheça o livro Zoé">Descubra o livro ↗</a></figcaption></figure></div><div class="hero-foot"><span>Livros para atravessar ideias e territórios</span><a href="#leituras">Continue explorando ↓</a></div></section><section class="section" id="leituras"><div class="sectionhead"><div><div class="chapter"><span>01</span> Percursos de leitura</div><h2>Encontros em papel.</h2></div><a href="catalogo.html">Todo o catálogo ↗</a></div><div class="grid featured-grid">{''.join(card(b) for b in featured)}</div></section><section class="reading-paths"><div class="chapter"><span>02</span> Coleções</div><h2>Por onde começa<br>a sua curiosidade?</h2><a class="path-link" href="catalogo.html?collection=Antropologia+Hoje"><span class="number">I.</span><h3>Antropologia Hoje</h3><p>Modos de viver, relações e culturas. Leituras que convidam a ampliar o olhar.</p><span class="arrow" aria-hidden="true">↗</span></a><a class="path-link" href="catalogo.html?collection=Brasil+Rebelde"><span class="number">II.</span><h3>Brasil Rebelde</h3><p>Histórias de conflitos e transformações para pensar a formação do país.</p><span class="arrow" aria-hidden="true">↗</span></a></section><section class="editorial"><div><span class="eyebrow">03 / Nossa casa editorial</span><h2>Feitos de papel.<br>Movidos por<br><em>paixão.</em></h2></div><div><p>A Terceiro Nome começou numa casinha nos fundos de um quintal. Os livros ocuparam a casa, atravessaram a vida e encontraram seus leitores.</p><p>Seguimos com o olhar voltado para o Brasil: suas raízes, suas belezas e seus desafios.</p><a href="sobreaeditora.html">Entre na nossa história ↗</a></div></section>'''
page('index.html','Livros, encontros e descobertas',hero)
collections=sorted({b['collection'] or 'Outros títulos' for b in books})
options=''.join(f'<option value="{e(c)}">{e(c)}</option>' for c in collections)
page('catalogo.html','Catálogo de livros',f'''<section class="page-heading"><span class="eyebrow">Encontre sua próxima leitura</span><h1>Nosso catálogo<span style="color:var(--red)">.</span></h1><p>Explore livros, autores e ideias. Uma biblioteca de encontros com o Brasil e com o mundo.</p></section><div id="filters" class="filters" hidden><label>Busque uma leitura<input id="search" type="search" placeholder="Título, autor ou ISBN" autocomplete="off"></label><label>Coleção<select id="collection"><option value="">Todas as coleções</option>{options}</select></label><label>Ordenar por<select id="sort"><option value="title">Título: A–Z</option><option value="author">Autoria: A–Z</option></select></label></div><noscript><p class="nojs-note">Todos os livros estão listados abaixo. Use a busca do navegador para encontrar um título.</p></noscript><div class="resultsbar"><span id="result-count" role="status" aria-live="polite">{len(books)} livros</span><button class="textbutton" id="clear" type="button">Limpar filtros</button></div><section class="section" aria-label="Livros"><div class="grid" data-catalog>{''.join(card(b) for b in books)}</div><div class="empty" id="empty" hidden><h2>Nenhum livro por aqui.</h2><p>Tente outro título, autor ou ISBN, ou limpe os filtros.</p></div><div class="more"><button class="button secondary" id="more" type="button" hidden>Mostrar mais livros</button></div></section>''')
for b in books:
    facts=[('Autoria / créditos',b['author']),('Coleção',b['collection']),('ISBN',b['isbn']),('Páginas',b['pages']),('Formato',b['format']),('Acabamento',b['binding'])]
    dl=''.join(f'<div><dt>{e(k)}</dt><dd>{e(v)}</dd></div>' for k,v in facts if v)
    retailer=b['commerce']['externalUrl']
    assert urlparse(retailer).hostname=='www.martinsfontespaulista.com.br' and retailer.startswith('https://')
    verified=b['commerce']['externalProductVerified'];cta='Ver este livro na Martins Fontes' if verified else 'Visitar Martins Fontes Paulista'
    description=b['description'][0] if b['description'] else f"Conheça {b['title']}, de {b['author']}, na Editora Terceiro Nome."
    body=f'''<nav class="breadcrumb" aria-label="Caminho de navegação"><a href="index.html">Início</a> / <a href="catalogo.html">Catálogo</a> / Livro</nav><section class="detail"><div class="detail-cover"><img src="{asset(b)}" alt="Capa de {e(b['title'])}" width="700" height="900"></div><div><span class="eyebrow">{e(b['collection'] or 'Editora Terceiro Nome')}</span><h1>{e(b['title'])}</h1><p class="byline">{e(b['author'])}</p><div class="purchase"><a class="button" href="{e(retailer)}" target="_blank" rel="noopener noreferrer">{cta} ↗</a><p>A compra acontece no site da livraria, em uma nova aba. Consulte lá os preços e a disponibilidade.{'' if verified else ' Procure pelo título ou ISBN deste livro.'}</p></div><dl class="facts">{dl}</dl></div></section><section class="prose"><h2>Sobre o livro</h2>{''.join('<p>'+e(p)+'</p>' for p in b['description']) or '<p>Consulte a ficha técnica acima para conhecer esta edição.</p>'}<a href="catalogo.html">← Voltar ao catálogo</a></section>'''
    schema={'@context':'https://schema.org','@type':'Book','name':b['title'],'inLanguage':'pt-BR','publisher':{'@type':'Organization','name':'Editora Terceiro Nome'}}
    if b['isbn']:schema['isbn']=b['isbn']
    page(b['legacyPath'],b['title'],body,description[:160],schema)
raw=(ROOT.parent/'sobreaeditora.html').read_text()
paras=[html.unescape(re.sub('<[^>]+>',' ',x)) for x in re.findall(r'<p\b[^>]*>(.*?)</p>',raw,re.S)]
start=next(i for i,p in enumerate(paras) if 'Lá se vão' in p);end=next(i for i,p in enumerate(paras) if 'E de repente' in p)
about=''.join('<p>'+e(' '.join(p.split()))+'</p>' for p in paras[start:end+1] if p.strip())
page('sobreaeditora.html','A editora',f'<section class="page-heading"><span class="eyebrow">Terceiro Nome</span><h1>Uma casa que faz<br>livros com paixão.</h1></section><article class="prose">{about}<p class="reading-note">Texto institucional preservado do acervo do site original.</p><a class="button" href="catalogo.html">Conheça nossos livros ↗</a></article>')
page('contato.html','Contato',f'''<section class="page-heading"><span class="eyebrow">Vamos conversar</span><h1>O próximo encontro<br>começa aqui.</h1></section><section class="prose"><h2>Fale com a editora</h2><p>Acompanhe a Terceiro Nome e entre em contato pelo perfil da editora no Instagram.</p><div class="contact-options"><a class="button" href="{config['contactInstagram']}" target="_blank" rel="noopener noreferrer">Instagram da editora ↗</a></div><h2>Onde comprar</h2><p>As compras são realizadas na Martins Fontes Paulista. Consulte a livraria para informações sobre disponibilidade, pagamento e entrega.</p><a href="{config['retailerUrl']}" target="_blank" rel="noopener noreferrer">Visitar o site da livraria ↗</a></section>''')
aliases=json.loads((ROOT/'data/aliases.json').read_text())
aliases.update({'produtos.html':'catalogo.html','catalogo-2.html':'catalogo.html','pesquisa.html':'catalogo.html','selecao_produtos.html':'catalogo.html','catalogo - Copia.html':'catalogo.html','vendas.html':'contato.html','formulario.html':'contato.html','venda_exclusiva.html':'contato.html','pix.html':'contato.html'})
for old,new in aliases.items():
    (DIST/old).write_text(f'<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="robots" content="noindex"><meta http-equiv="refresh" content="0;url={href(new)}"><title>Página atualizada</title></head><body><a href="{href(new)}">Acessar página atualizada</a></body></html>')
(ROOT/'docs/redirects.json').write_text(json.dumps(aliases,ensure_ascii=False,indent=2))
page('404.html','Página não encontrada','<section class="page-heading"><span class="eyebrow">Página não encontrada</span><h1>Vamos encontrar<br>outra leitura?</h1><p>O endereço pode ter mudado. Explore nosso catálogo para continuar.</p><a class="button" href="catalogo.html">Ir para o catálogo</a></section>')
(DIST/'robots.txt').write_text('User-agent: *\nDisallow: /\n' if not config['indexable'] else 'User-agent: *\nAllow: /\n')
if config['canonicalOrigin']:
    urls=[config['canonicalOrigin'].rstrip('/')+'/'+href(n) for n in ['index.html','catalogo.html','sobreaeditora.html','contato.html']+[b['legacyPath'] for b in books]]
    (DIST/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+e(u)+'</loc></url>' for u in urls)+'</urlset>')
print(f'Build concluído: {len(books)} páginas de livros em {DIST}')
